INSERT INTO `biz_question` VALUES (79, 'typing', '1956 年美国达特茅斯会议正式提出 “人工智能（AI）” 概念，该年被视为人工智能元年。英国数学家阿兰・图灵在《计算机器与智能》中提出 “图灵测试”，以提问者判断失误率≥30% 作为机器具备人类智能的标准。人工智能发展并非一帆风顺，经历了三起两落的历程，不同阶段核心研究方向从符号推理逐步拓展。', 8, '1', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Y', 4, 143, 104, '19157727791', '2026-01-19 15:14:14', '19157727791', '2026-01-19 15:14:22');
INSERT INTO `biz_question` VALUES (80, 'choice', '被普遍认为 “人工智能元年” 的是哪一年', 8, '1', 1, '1956', '1943', '1978', '1999', 'A', NULL, NULL, NULL, NULL, 'N', NULL, NULL, 104, '19157727791', '2026-01-19 15:15:25', '', NULL);
INSERT INTO `biz_question` VALUES (81, 'practical', '操作题', 8, '1', 1, NULL, NULL, NULL, NULL, NULL, NULL, '/profile/upload/2026/01/19/课后作业_20260119151609A133.docx', '/profile/upload/2026/01/19/课后作业_20260119151609A133.pdf', 'success', 'Y', NULL, NULL, 104, '19157727791', '2026-01-19 15:16:24', '', NULL);
INSERT INTO `biz_question` VALUES (104, 'choice', '在HTML网页代码中，用于定义网页“主体内容”的标签是？', 8, '0', 1, '<head>', '<body>', '<title>', '<html>', 'B', '', NULL, NULL, NULL, 'N', NULL, NULL, 104, '19157727791', '2026-01-20 12:56:56', '', NULL);
INSERT INTO `biz_question` VALUES (105, 'choice', '想要在网页中插入一张图片，应该使用以下哪个标签？', 8, '0', 1, '<img>', '<pic>', '<image>', '<src>', 'A', '', NULL, NULL, NULL, 'N', NULL, NULL, 104, '19157727791', '2026-01-20 12:56:56', '', NULL);
INSERT INTO `biz_question` VALUES (106, 'choice', '下列关于HTML标签的说法，错误的是？', 8, '0', 1, 'HTML标签通常是成对出现的', '<br>标签用于换行，它没有结束标签', 'HTML是不区分大小写的', '<html>标签表示网页的结束', 'D', '', NULL, NULL, NULL, 'N', NULL, NULL, 104, '19157727791', '2026-01-20 12:56:56', '', NULL);
INSERT INTO `biz_question` VALUES (107, 'choice', '网页文件的扩展名通常是？', 8, '0', 1, '.txt', '.doc', '.html', '.ppt', 'C', '', NULL, NULL, NULL, 'N', NULL, NULL, 104, '19157727791', '2026-01-20 12:56:56', '', NULL);
INSERT INTO `biz_question` VALUES (108, 'choice', '如果要在网页标题栏显示“期末考试”，代码应写在哪个标签之间？', 8, '0', 1, '<body>...</body>', '<p>...</p>', '<title>...</title>', '<h1>...</h1>', 'C', '', NULL, NULL, NULL, 'N', NULL, NULL, 104, '19157727791', '2026-01-20 12:56:57', '', NULL);
INSERT INTO `biz_question` VALUES (109, 'judgment', '我们可以使用“记事本”软件编写HTML代码，保存时将后缀名改为.html即可用浏览器打开。', 8, '0', 1, '', '', '', '', 'T', '', NULL, NULL, NULL, 'N', NULL, NULL, 104, '19157727791', '2026-01-20 12:56:57', '', NULL);
INSERT INTO `biz_question` VALUES (110, 'typing', '互联网应用极大改变了我们的生活方式，从在线学习到电子支付，数据早已无处不在。网页是互联网数据呈现的重要载体，而超文本标记语言HTML则是制作网页的基石。在HTML代码中，标签通常成对出现，例如BODY标签定义了网页的主体内容，IMG标签用于插入图像。我们在享受便捷的同时，绝不能忽视网络安全隐患。为了保护个人隐私和数据资产，我们需要养成定期备份数据的习惯。', 8, '0', 1, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 4, 178, 104, '19157727791', '2026-01-20 12:56:57', '', NULL);
INSERT INTO `biz_question` VALUES (111, 'typing', '核心知识点：控制形态主要分为人工干预控制和自动控制。人工干预控制需人直接或全程干预，如手动控制电灯开关；自动控制无需人参与即可实现目标，如感应灯自动亮灭。两者核心区别在于，输出量能否返回输入端与输入量比较，形成闭合环路。', 6, '1', 2, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Y', 5, 110, 104, '19157727791', '2026-01-20 13:01:00', '', NULL);
INSERT INTO `biz_question` VALUES (112, 'practical', '操作题', 8, '0', 1, NULL, NULL, NULL, NULL, NULL, NULL, '/profile/upload/2026/01/20/课后作业_20260120130453A040.docx', '/profile/upload/2026/01/20/课后作业_20260120130453A040.pdf', 'success', 'Y', NULL, NULL, 104, '19157727791', '2026-01-20 13:05:03', '', NULL);
INSERT INTO `biz_question` VALUES (113, 'choice', '下列哪一项属于算法的基本特征？', 6, '0', 1, '随意性', '有限性', '娱乐性', '模糊性', 'B', NULL, NULL, NULL, NULL, 'Y', NULL, NULL, 104, '19157727791', '2026-01-21 12:35:37', '', NULL);
INSERT INTO `biz_question` VALUES (114, 'choice', '在“鸡兔同笼”问题中，常用的算法思想是', 6, '0', 1, '排序法 ', '枚举法', '加密法', '压缩', 'B', NULL, NULL, NULL, NULL, 'Y', NULL, NULL, 104, '19157727791', '2026-01-21 12:36:29', '', NULL);
INSERT INTO `biz_question` VALUES (115, 'choice', '猜数字游戏中，用于反复让用户输入的结构是', 6, '0', 1, '顺序结构', '分支结构', '循环结构', '选择结构', 'C', NULL, NULL, NULL, NULL, 'Y', NULL, NULL, 104, '19157727791', '2026-01-21 12:37:19', '', NULL);
INSERT INTO `biz_question` VALUES (116, 'judgment', '算法对生活只有好处，没有任何问题', 6, '0', NULL, NULL, NULL, NULL, NULL, 'F', NULL, NULL, NULL, NULL, 'Y', NULL, NULL, 104, '19157727791', '2026-01-21 12:37:47', '', NULL);
INSERT INTO `biz_question` VALUES (117, 'judgment', '二分查找比顺序查找效率低', 6, '0', NULL, NULL, NULL, NULL, NULL, 'F', NULL, NULL, NULL, NULL, 'Y', NULL, NULL, 104, '19157727791', '2026-01-21 12:38:09', '', NULL);
INSERT INTO `biz_question` VALUES (118, 'practical', '六年级', 6, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '/profile/upload/2026/01/21/考试操作题_20260121124339A213.docx', '/profile/upload/2026/01/21/考试操作题_20260121124339A213.pdf', 'success', 'Y', NULL, NULL, 104, '19157727791', '2026-01-21 12:43:53', '', NULL);
INSERT INTO `biz_question` VALUES (121, 'typing', '人工智能应用的表现形式大致可分为能听、能说、能看、能写、会思考、会学习和会行动等方面 。本课核心掌握三大应用：一是机器翻译，它以自然语言理解为核心，结合语言学知识实现精准翻译 。二是无人驾驶，它通过感知系统识别环境、决策系统规划导航、执行系统控制车辆运行，三系统协同合作实现自动行驶 。三是人机博弈，运用计算机技术与博弈思想，结合深度学习等技术，使机器能像人类一样从事高度智能的对策活动 。', 8, '1', 2, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Y', 5, 191, 104, '19157727791', '2026-03-03 09:22:20', '', NULL);
INSERT INTO `biz_question` VALUES (122, 'typing', '数据、算法、算力构成人工智能的三大技术基础，三者相互影响、相互促进、缺一不可。数据是人工智能的基础，有了足够的数据，人工智能就能不断学习和提高。算法是人工智能的核心，实现了从数据中发现规律、预测结果和决策的过程，是让计算机具有类似人类智能的关键所在。算力即计算机的计算能力，代表着数据处理能力的强弱，是人工智能发展的动力。从中央处理器、图形处理器到人工智能专用芯片，算力的提升让大规模数据处理效率得到飞跃，推动人工智能为人类创造出更多可能', 8, '1', 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Y', 6, 219, 104, '19157727791', '2026-03-03 10:16:49', '', NULL);
INSERT INTO `biz_question` VALUES (123, 'practical', '人工智能技术基础课后练习', 8, '1', 3, NULL, NULL, NULL, NULL, NULL, NULL, '/profile/upload/2026/03/03/八下第3课作业_20260303101723A002.docx', '/profile/upload/2026/03/03/八下第3课作业_20260303101723A002.pdf', 'failed', 'Y', NULL, NULL, 104, '19157727791', '2026-03-03 10:17:39', '', NULL);
INSERT INTO `biz_question` VALUES (124, 'typing', '在自动控制系统中，将输出量通过检测装置反馈到输入端并与输入量进行比较的过程，就是反馈 。通过输出量和输入量的比较，实现控制系统的输出在预设范围内，反馈在其中发挥了重要的作用 。反馈在保证系统正常运行中也发挥了重要的作用 。', 6, '1', 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Y', 6, 108, 104, '19157727791', '2026-03-03 11:07:50', '', NULL);
INSERT INTO `biz_question` VALUES (127, 'practical', '人工智能应用课后练习', 8, '1', 2, NULL, NULL, NULL, NULL, NULL, NULL, '/profile/upload/2026/03/04/第2课人工智能应用作业1_20260304091828A001.docx', '/profile/upload/2026/03/04/第2课人工智能应用作业1_20260304091828A001.pdf', 'success', 'Y', NULL, NULL, 104, '19157727791', '2026-03-04 09:18:36', '', NULL);
INSERT INTO `biz_question` VALUES (128, 'typing', '物联网就像给世界装上了 “五官”，能让物体互相交流、自动工作，而感知与识别技术就是它的核心。感知技术依靠传感器，能收集温度、湿度、光线、声音等信息，就像我们用眼睛看、耳朵听。识别技术可以分辨物体、人脸、指纹和二维码，让设备 “认出” 目标。在生活里，这些技术随处可见：智能手环感知心跳，超市扫码器识别商品，门禁刷脸开门，智能家居根据环境自动调节。它们让生活更方便、更安全。', 7, '0', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Y', 5, 183, 896, '675077', '2026-03-05 09:28:14', '', NULL);
INSERT INTO `biz_question` VALUES (129, 'typing', '图像识别技术是人工智能的一个重要领域。它是指对图像进行对象识别，以识别各种不同模式的目标和对像的技术。 图像识别技术可能是以图像的主要特征为基础的。每个图像都有它的特征，如字母A有个尖，P有个圈、而Y的中心有个锐角等。由此可见，在图像识别过程中，知觉机制必须排除输入的多余信息,抽出关键的信息。同时,在大脑里必定有一个负责整合信息的机制，它能把分阶段获得的信息整理成一个完整的知觉映象。', 8, '1', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Y', 5, 192, 896, '675077', '2026-03-09 09:06:03', '', NULL);
INSERT INTO `biz_question` VALUES (130, 'practical', '上传图像识别导学单', 8, '1', 1, NULL, NULL, NULL, NULL, NULL, NULL, '/profile/upload/2026/03/09/导学单 - 图像识别技术_20260309093017A180.docx', '/profile/upload/2026/03/09/导学单 - 图像识别技术_20260309093017A180.pdf', 'failed', 'Y', NULL, NULL, 896, '675077', '2026-03-09 09:30:38', '', NULL);
INSERT INTO `biz_question` VALUES (131, 'practical', '人工智能基础课后练习', 8, '1', 3, NULL, NULL, NULL, NULL, NULL, NULL, '/profile/upload/2026/03/09/八下第3课作业_20260309104049A181.docx', '/profile/upload/2026/03/09/八下第3课作业_20260309104049A181.pdf', 'success', 'Y', NULL, NULL, 104, '19157727791', '2026-03-09 10:41:02', '', NULL);
