INSERT INTO `biz_question` VALUES (161, 'choice', '水分传感器是物联网架构中（     ）的设备？', 7, '1', 2, '应用层', '平台层', '网络层', '感知层', 'D', '', NULL, NULL, NULL, 'N', NULL, NULL, 1587, '960250', '2026-03-09 16:37:05', '', NULL);
INSERT INTO `biz_question` VALUES (162, 'choice', '利用云计算、数据挖掘以及模糊识别等智能技术，对接收到的海量数据与信息进行分析、处理，以进行智能化决策，体现了物联网的（         ）特征。', 7, '1', 2, '全面感知', '可靠传递', '可靠决策', '智能处理', 'D', '', NULL, NULL, NULL, 'N', NULL, NULL, 1587, '960250', '2026-03-09 16:37:05', '', NULL);
INSERT INTO `biz_question` VALUES (163, 'choice', '物联网的（       ）功能相当于人的大脑，运用智能技术对海量数据和信息进行处理。', 7, '1', 2, '应用层', '平台层', '网络层', '感知层', 'B', '', NULL, NULL, NULL, 'N', NULL, NULL, 1587, '960250', '2026-03-09 16:37:05', '960250', '2026-03-09 16:37:18');
INSERT INTO `biz_question` VALUES (164, 'choice', '自动浇灌物联系统原型中，物联数据中台是属于（       ）', 7, '1', 2, '应用层', '平台层', '网络层', '感知层', 'B', '', NULL, NULL, NULL, 'N', NULL, NULL, 1587, '960250', '2026-03-09 16:37:05', '960250', '2026-03-09 16:37:14');
INSERT INTO `biz_question` VALUES (165, 'choice', '关于只允许本小区车辆进入的无人看守停车场，下列说法不正确的是（     ）', 7, '1', 2, '利用摄像头拍录汽车牌照图片属于物联网感知层；', '将图片传送到平台层进行数据处理需要通过网络层。', '平台层中运用人工智能图像识别技术识别图片中的车牌号码判断是否为本小区车辆，体现了物联网的全面感知特征。', '拦车杆根据指令升起，是物联网应用层上的智能应用。', 'C', '', NULL, NULL, NULL, 'N', NULL, NULL, 1587, '960250', '2026-03-09 16:37:05', '960250', '2026-03-09 16:37:21');
INSERT INTO `biz_question` VALUES (166, 'judgment', '物联网体系架构中，平台层相当于人的皮肤', 7, '1', 2, '', '', '', '', 'F', '', NULL, NULL, NULL, 'N', NULL, NULL, 1587, '960250', '2026-03-09 16:37:05', '960250', '2026-03-09 16:37:36');
INSERT INTO `biz_question` VALUES (167, 'typing', '物联网是互联网充分发展的产物，是物理世界和数字世界之间的桥梁。物联网具有全面感知、可靠传递、智能处理等特征。物联网一般由感知层、网络层、平台层、应用层四层组成。感知层是物联网的底层，相当于人的眼、耳等器官，负责物联网的物体识别和信息采集。感知层是物联网的底层，相当于人的眼、耳等器官，负责物联网的物体识别和信息采集。平台层是在云平台基础上构建的基础计算设施，功能相当于人的大脑，运用智能技术对海量数据和信息进行处理。应用层是物联网和用户的接口。', 7, '1', 2, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 6, 222, 1587, '960250', '2026-03-09 16:37:05', '', NULL);
INSERT INTO `biz_question` VALUES (168, 'typing', '人工智能的发展经历了三起两落的漫长过程，如今的全面爆发主要得益于数据算法和算力这三大基础技术的飞跃。人工智能正深刻改变着我们的社会，它不仅赋能生活，通过智能管家和智慧城市让日常出行更加便捷，还赋能经济，在全自动化的智慧港口和精准测算的智慧农业等领域大幅提高了生产效率。与此同时，人工智能在推动社会进步的同时，也带来了传统就业岗位减少和数据隐私安全等现实挑战。', 8, '1', 4, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Y', 5, 179, 104, '19157727791', '2026-03-10 10:46:17', '', NULL);
INSERT INTO `biz_question` VALUES (169, 'practical', '课堂探究', 8, '1', 4, NULL, NULL, NULL, NULL, NULL, NULL, '/profile/upload/2026/03/10/课堂探究任务单（学生端）_20260310151507A352.docx', '/profile/upload/2026/03/10/课堂探究任务单（学生端）_20260310151507A352.pdf', 'success', 'Y', NULL, NULL, 104, '19157727791', '2026-03-10 15:15:15', '', NULL);
INSERT INTO `biz_question` VALUES (170, 'typing', '反馈的实现是通过传感器对系统的输出量进行检测，并与输入量比较来判断是否达成预期的过程。传感器如同人体感官，负责获取环境信息。比较器接收传感器传回的实际输出量，与预设输入量对比计算出偏差值。', 6, '1', 4, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Y', 5, 94, 104, '19157727791', '2026-03-10 19:45:04', '', NULL);
INSERT INTO `biz_question` VALUES (171, 'practical', '观看智能浇灌系统和智能通风系统展示视频，选择其一填表：\n', 7, '1', 2, NULL, NULL, NULL, NULL, NULL, NULL, '/profile/upload/2026/03/11/课堂任务_20260311145344A484.docx', '/profile/upload/2026/03/11/课堂任务_20260311145344A484.pdf', 'success', 'Y', NULL, NULL, 1587, '960250', '2026-03-11 14:54:28', '', NULL);
