INSERT INTO `sys_oper_log` VALUES (509, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '19157727791', '大徐小学', '/business/question', '127.0.0.1', '内网IP', '{\"createBy\":\"19157727791\",\"createTime\":\"2026-01-19 15:14:13\",\"creatorId\":104,\"grade\":8,\"isPublic\":\"Y\",\"lessonNum\":1,\"params\":{},\"questionContent\":\"1956 年美国达特茅斯会议正式提出 “人工智能（AI）” 概念，该年被视为人工智能元年。英国数学家阿兰・图灵在《计算机器与智能》中提出 “图灵测试”，以提问者判断失误率≥30% 作为机器具备人类智能的标准。人工智能发展并非一帆风顺，经历了三起两落的历程，不同阶段核心研究方向从符号推理逐步拓展。\",\"questionId\":79,\"questionType\":\"typing\",\"scoringItems\":[],\"semester\":\"1\",\"typingDuration\":5,\"wordCount\":143}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-01-19 15:14:13', 9);
