INSERT INTO `sys_oper_log` VALUES (526, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '19157727791', '大徐小学', '/business/question', '127.0.0.1', '内网IP', '{\"createBy\":\"19157727791\",\"createTime\":\"2026-01-20 13:00:59\",\"creatorId\":104,\"grade\":6,\"isPublic\":\"Y\",\"lessonNum\":2,\"params\":{},\"questionContent\":\"核心知识点：控制形态主要分为人工干预控制和自动控制。人工干预控制需人直接或全程干预，如手动控制电灯开关；自动控制无需人参与即可实现目标，如感应灯自动亮灭。两者核心区别在于，输出量能否返回输入端与输入量比较，形成闭合环路。\",\"questionId\":111,\"questionType\":\"typing\",\"scoringItems\":[],\"semester\":\"1\",\"typingDuration\":5,\"wordCount\":110}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-01-20 13:00:59', 20);
INSERT INTO `sys_oper_log` VALUES (527, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '19157727791', '大徐小学', '/business/lesson/save-all', '127.0.0.1', '内网IP', '{\"assignedClassCodes\":[\"2班\",\"1班\",\"8班\",\"10班\",\"5班\",\"6班\"],\"grade\":6,\"lessonId\":26,\"lessonNum\":2,\"lessonTitle\":\"2-控制的形态\",\"params\":{},\"questions\":[{\"orderNum\":1,\"params\":{},\"questionContent\":\"核心知识点：控制形态主要分为人工干预控制和自动控制。人工干预控制需人直接或全程干预，如手动控制电灯开关；自动控制无需人参与即可实现目标，如感应灯自动亮灭。两者核心区别在于，输出量能否返回输入端与输入量比较，形成闭合环路。\",\"questionId\":111,\"questionScore\":100,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":110}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"0\",\"shuffleMode\":0}', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"2班\",\"1班\",\"8班\",\"10班\",\"5班\",\"6班\"],\"grade\":6,\"lessonId\":26,\"lessonNum\":2,\"lessonTitle\":\"2-控制的形态\",\"params\":{},\"questions\":[{\"orderNum\":1,\"params\":{},\"questionContent\":\"核心知识点：控制形态主要分为人工干预控制和自动控制。人工干预控制需人直接或全程干预，如手动控制电灯开关；自动控制无需人参与即可实现目标，如感应灯自动亮灭。两者核心区别在于，输出量能否返回输入端与输入量比较，形成闭合环路。\",\"questionId\":111,\"questionScore\":100,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":110}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"0\",\"shuffleMode\":0}}', 0, NULL, '2026-01-20 13:01:13', 62);
INSERT INTO `sys_oper_log` VALUES (528, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '19157727791', '大徐小学', '/business/lesson/save-all', '127.0.0.1', '内网IP', '{\"assignedClassCodes\":[\"2班\",\"4班\",\"6班\",\"7班\"],\"grade\":8,\"lessonId\":31,\"lessonNum\":1,\"lessonTitle\":\"2-考试\",\"params\":{},\"questions\":[{\"answer\":\"\",\"optionA\":\"\",\"optionB\":\"\",\"optionC\":\"\",\"optionD\":\"\",\"orderNum\":1,\"params\":{},\"questionContent\":\"互联网应用极大改变了我们的生活方式，从在线学习到电子支付，数据早已无处不在。网页是互联网数据呈现的重要载体，而超文本标记语言HTML则是制作网页的基石。在HTML代码中，标签通常成对出现，例如BODY标签定义了网页的主体内容，IMG标签用于插入图像。我们在享受便捷的同时，绝不能忽视网络安全隐患。为了保护个人隐私和数据资产，我们需要养成定期备份数据的习惯。\",\"questionId\":110,\"questionScore\":40,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":4,\"wordCount\":178},{\"answer\":\"C\",\"optionA\":\"<body>...</body>\",\"optionB\":\"<p>...</p>\",\"optionC\":\"<title>...</title>\",\"optionD\":\"<h1>...</h1>\",\"orderNum\":2,\"params\":{},\"questionContent\":\"如果要在网页标题栏显示“期末考试”，代码应写在哪个标签之间？\",\"questionId\":108,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"optionA\":\"<head>\",\"optionB\":\"<body>\",\"optionC\":\"<title>\",\"optionD\":\"<html>\",\"orderNum\":3,\"params\":{},\"questionContent\":\"在HTML网页代码中，用于定义网页“主体内容”的标签是？\",\"questionId\":104,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"A\",\"optionA\":\"<img>\",\"optionB\":\"<pic>\",\"optionC\":\"<image>\",\"optionD\":\"<src>\",\"orderNum\":4,\"params\":{},\"questionContent\":\"想要在网页中插入一张图片，应该使用以下哪个标签？\",\"questionId\":105,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"D\",\"optionA\":\"HTML标签通常是成对出现的\",\"optionB\":\"<br>标签用于换行，它没有结束标签\",\"optionC\":\"HTML是不区分大小写的\",\"optionD\":\"<html>标签表示网页的结束\",\"orderNum\":5,\"params\":{},\"questionContent\":\"下列关于HTML标签的说法，错误的是？\",\"questionId\":106,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"C\",\"optionA\":\".txt\",\"optionB\":\".doc\",\"optionC\":\".html\",\"optionD\":\".ppt\",\"orderNum\":6,\"params\":{},\"questionContent\":\"网页文件的扩展名通常是？\",\"questionId\":107,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"T\",\"optionA\":\"\",\"optionB\":\"\",\"optionC\":\"\",\"optionD\":\"\",\"orderNum\":7,\"params\":{},\"questionContent\":\"我们可以使用“记事本”软件编写HTML代码，保存时将后缀名改为.html即可用浏览器打开。\",\"questionId\":109,\"questionScore\":10,\"questionType\":\"judgment\",\"sc', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"2班\",\"4班\",\"6班\",\"7班\"],\"grade\":8,\"lessonId\":31,\"lessonNum\":1,\"lessonTitle\":\"2-考试\",\"params\":{},\"questions\":[{\"orderNum\":1,\"params\":{},\"questionContent\":\"互联网应用极大改变了我们的生活方式，从在线学习到电子支付，数据早已无处不在。网页是互联网数据呈现的重要载体，而超文本标记语言HTML则是制作网页的基石。在HTML代码中，标签通常成对出现，例如BODY标签定义了网页的主体内容，IMG标签用于插入图像。我们在享受便捷的同时，绝不能忽视网络安全隐患。为了保护个人隐私和数据资产，我们需要养成定期备份数据的习惯。\",\"questionId\":110,\"questionScore\":40,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":4,\"wordCount\":178},{\"answer\":\"C\",\"optionA\":\"<body>...</body>\",\"optionB\":\"<p>...</p>\",\"optionC\":\"<title>...</title>\",\"optionD\":\"<h1>...</h1>\",\"orderNum\":2,\"params\":{},\"questionContent\":\"如果要在网页标题栏显示“期末考试”，代码应写在哪个标签之间？\",\"questionId\":108,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"optionA\":\"<head>\",\"optionB\":\"<body>\",\"optionC\":\"<title>\",\"optionD\":\"<html>\",\"orderNum\":3,\"params\":{},\"questionContent\":\"在HTML网页代码中，用于定义网页“主体内容”的标签是？\",\"questionId\":104,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"A\",\"optionA\":\"<img>\",\"optionB\":\"<pic>\",\"optionC\":\"<image>\",\"optionD\":\"<src>\",\"orderNum\":4,\"params\":{},\"questionContent\":\"想要在网页中插入一张图片，应该使用以下哪个标签？\",\"questionId\":105,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"D\",\"optionA\":\"HTML标签通常是成对出现的\",\"optionB\":\"<br>标签用于换行，它没有结束标签\",\"optionC\":\"HTML是不区分大小写的\",\"optionD\":\"<html>标签表示网页的结束\",\"orderNum\":5,\"params\":{},\"questionContent\":\"下列关于HTML标签的说法，错误的是？\",\"questionId\":106,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"C\",\"optionA\":\".txt\",\"optionB\":\".doc\",\"optionC\":\".html\",\"optionD\":\".ppt\",\"orderNum\":6,\"params\":{},\"questionContent\":\"网页文件的扩展名通常是？\",\"questionId\":107,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"T\",\"orderNum\":7,\"params\":{},\"questionContent\":\"我们可以使用“记事本”软件编写HTML代码，保存时将后缀名改为.html即可用浏览器打开。\",\"questionId\":109,\"questionScore\":10,\"questionType\":\"judgment\",\"scoringItems\":[]}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"0\",\"shuff', 0, NULL, '2026-01-20 13:02:20', 22);
