INSERT INTO `sys_oper_log` VALUES (600, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '19157727791', '大徐小学', '/business/lesson/save-all', '127.0.0.1', '内网IP', '{\"assignedClassCodes\":[\"2班\",\"1班\",\"10班\",\"5班\",\"6班\",\"3班\",\"4班\",\"7班\",\"8班\"],\"grade\":6,\"lessonId\":26,\"lessonNum\":2,\"lessonTitle\":\"2-控制的形态\",\"params\":{},\"questions\":[{\"lessonId\":26,\"orderNum\":1,\"params\":{},\"questionContent\":\"核心知识点：控制形态主要分为人工干预控制和自动控制。人工干预控制需人直接或全程干预，如手动控制电灯开关；自动控制无需人参与即可实现目标，如感应灯自动亮灭。两者核心区别在于，输出量能否返回输入端与输入量比较，形成闭合环路。\",\"questionId\":111,\"questionScore\":100,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":110}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"0\",\"shuffleMode\":0}', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"2班\",\"1班\",\"10班\",\"5班\",\"6班\",\"3班\",\"4班\",\"7班\",\"8班\"],\"grade\":6,\"lessonId\":26,\"lessonNum\":2,\"lessonTitle\":\"2-控制的形态\",\"params\":{},\"questions\":[{\"lessonId\":26,\"orderNum\":1,\"params\":{},\"questionContent\":\"核心知识点：控制形态主要分为人工干预控制和自动控制。人工干预控制需人直接或全程干预，如手动控制电灯开关；自动控制无需人参与即可实现目标，如感应灯自动亮灭。两者核心区别在于，输出量能否返回输入端与输入量比较，形成闭合环路。\",\"questionId\":111,\"questionScore\":100,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":110}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"0\",\"shuffleMode\":0}}', 0, NULL, '2026-03-03 10:19:24', 35);
INSERT INTO `sys_oper_log` VALUES (601, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '19157727791', '大徐小学', '/business/question', '127.0.0.1', '内网IP', '{\"createBy\":\"19157727791\",\"createTime\":\"2026-03-03 11:07:50\",\"creatorId\":104,\"grade\":6,\"isPublic\":\"Y\",\"lessonNum\":3,\"params\":{},\"questionContent\":\"在自动控制系统中，将输出量通过检测装置反馈到输入端并与输入量进行比较的过程，就是反馈 。通过输出量和输入量的比较，实现控制系统的输出在预设范围内，反馈在其中发挥了重要的作用 。反馈在保证系统正常运行中也发挥了重要的作用 。\",\"questionId\":124,\"questionType\":\"typing\",\"scoringItems\":[],\"semester\":\"1\",\"typingDuration\":6,\"wordCount\":108}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-03 11:07:50', 17);
