INSERT INTO `sys_oper_log` VALUES (639, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '19157727791', '大徐小学', '/business/lesson/save-all', '127.0.0.1', '内网IP', '{\"assignedClassCodes\":[\"3班\",\"1班\",\"5班\",\"4班\"],\"grade\":8,\"lessonId\":34,\"lessonNum\":1,\"lessonTitle\":\"3-人工智能技术基础课后练习\",\"params\":{},\"questions\":[{\"lessonId\":34,\"orderNum\":1,\"params\":{},\"questionContent\":\"数据、算法、算力构成人工智能的三大技术基础，三者相互影响、相互促进、缺一不可。数据是人工智能的基础，有了足够的数据，人工智能就能不断学习和提高。算法是人工智能的核心，实现了从数据中发现规律、预测结果和决策的过程，是让计算机具有类似人类智能的关键所在。算力即计算机的计算能力，代表着数据处理能力的强弱，是人工智能发展的动力。从中央处理器、图形处理器到人工智能专用芯片，算力的提升让大规模数据处理效率得到飞跃，推动人工智能为人类创造出更多可能\",\"questionId\":122,\"questionScore\":60,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":6,\"wordCount\":219},{\"filePath\":\"/profile/upload/2026/03/03/八下第3课作业_20260303101723A002.docx\",\"lessonId\":34,\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/03/八下第3课作业_20260303101723A002.pdf\",\"questionContent\":\"人工智能技术基础课后练习\",\"questionId\":123,\"questionScore\":40,\"questionType\":\"practical\",\"scoringItems\":[{\"itemId\":21,\"itemName\":\"答案是否正确\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":123}]}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":0}', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"3班\",\"1班\",\"5班\",\"4班\"],\"grade\":8,\"lessonId\":34,\"lessonNum\":1,\"lessonTitle\":\"3-人工智能技术基础课后练习\",\"params\":{},\"questions\":[{\"lessonId\":34,\"orderNum\":1,\"params\":{},\"questionContent\":\"数据、算法、算力构成人工智能的三大技术基础，三者相互影响、相互促进、缺一不可。数据是人工智能的基础，有了足够的数据，人工智能就能不断学习和提高。算法是人工智能的核心，实现了从数据中发现规律、预测结果和决策的过程，是让计算机具有类似人类智能的关键所在。算力即计算机的计算能力，代表着数据处理能力的强弱，是人工智能发展的动力。从中央处理器、图形处理器到人工智能专用芯片，算力的提升让大规模数据处理效率得到飞跃，推动人工智能为人类创造出更多可能\",\"questionId\":122,\"questionScore\":60,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":6,\"wordCount\":219},{\"filePath\":\"/profile/upload/2026/03/03/八下第3课作业_20260303101723A002.do