INSERT INTO `sys_oper_log` VALUES (646, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '675077', '塔山中学', '/business/question', '127.0.0.1', '内网IP', '{\"createBy\":\"675077\",\"createTime\":\"2026-03-09 09:06:03\",\"creatorId\":896,\"grade\":8,\"isPublic\":\"Y\",\"lessonNum\":1,\"params\":{},\"questionContent\":\"图像识别技术是人工智能的一个重要领域。它是指对图像进行对象识别，以识别各种不同模式的目标和对像的技术。 图像识别技术可能是以图像的主要特征为基础的。每个图像都有它的特征，如字母A有个尖，P有个圈、而Y的中心有个锐角等。由此可见，在图像识别过程中，知觉机制必须排除输入的多余信息,抽出关键的信息。同时,在大脑里必定有一个负责整合信息的机制，它能把分阶段获得的信息整理成一个完整的知觉映象。\",\"questionId\":129,\"questionType\":\"typing\",\"scoringItems\":[],\"semester\":\"1\",\"typingDuration\":5,\"wordCount\":192}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-09 09:06:03', 15);
INSERT INTO `sys_oper_log` VALUES (647, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '675077', '塔山中学', '/business/lesson/save-all', '127.0.0.1', '内网IP', '{\"assignedClassCodes\":[\"1班\",\"3班\",\"4班\",\"5班\",\"6班\",\"7班\",\"8班\",\"9班\",\"10班\",\"2班\"],\"grade\":7,\"lessonId\":36,\"lessonNum\":1,\"lessonTitle\":\"感知与识别\",\"params\":{},\"questions\":[{\"orderNum\":1,\"params\":{},\"questionContent\":\"物联网就像给世界装上了 “五官”，能让物体互相交流、自动工作，而感知与识别技术就是它的核心。感知技术依靠传感器，能收集温度、湿度、光线、声音等信息，就像我们用眼睛看、耳朵听。识别技术可以分辨物体、人脸、指纹和二维码，让设备 “认出” 目标。在生活里，这些技术随处可见：智能手环感知心跳，超市扫码器识别商品，门禁刷脸开门，智能家居根据环境自动调节。它们让生活更方便、更安全。\",\"questionId\":128,\"questionScore\":100,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":183}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":0}', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"1班\",\"3班\",\"4班\",\"5班\",\"6班\",\"7班\",\"8班\",\"9班\",\"10班\",\"2班\"],\"grade\":7,\"lessonId\":36,\"lessonNum\":1,\"lessonTitle\":\"感知与识别\",\"params\":{},\"questions\":[{\"orderNum\":1,\"params\":{},\"questionContent\":\"物联网就像给世界装上了 “五官”，能让物体互相交流、自动工作，而感知与识别技术就是它的核心。感知技术依靠传感器，能收集温度、湿度、光线、声音等信息，就像我们用眼睛看、耳朵听。识别技术可以分辨物体、人脸、指纹和二维码，让设备 “认出” 目标。在生活里，这些技术随处可见：智能手环感知心跳，超市扫码器识别商品，门禁刷脸开门，智能家居根据环境自动调节。它们让生活更方便、更安全。\",\"questionId\":128,\"questionScore\":100,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":183}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":0}}', 0, NULL, '2026-03-09 09:06:39', 33);
INSERT INTO `sys_oper_log` VALUES (648, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '675077', '塔山中学', '/business/lesson/save-all', '127.0.0.1', '内网IP', '{\"assignedClassCodes\":[\"809班\",\"810班\",\"811班\"],\"grade\":8,\"lessonId\":37,\"lessonNum\":1,\"lessonTitle\":\"图像识别技术\",\"params\":{},\"questions\":[{\"orderNum\":1,\"params\":{},\"questionContent\":\"图像识别技术是人工智能的一个重要领域。它是指对图像进行对象识别，以识别各种不同模式的目标和对像的技术。 图像识别技术可能是以图像的主要特征为基础的。每个图像都有它的特征，如字母A有个尖，P有个圈、而Y的中心有个锐角等。由此可见，在图像识别过程中，知觉机制必须排除输入的多余信息,抽出关键的信息。同时,在大脑里必定有一个负责整合信息的机制，它能把分阶段获得的信息整理成一个完整的知觉映象。\",\"questionId\":129,\"questionScore\":100,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":192}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":0}', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"809班\",\"810班\",\"811班\"],\"grade\":8,\"lessonId\":37,\"lessonNum\":1,\"lessonTitle\":\"图像识别技术\",\"params\":{},\"questions\":[{\"orderNum\":1,\"params\":{},\"questionContent\":\"图像识别技术是人工智能的一个重要领域。它是指对图像进行对象识别，以识别各种不同模式的目标和对像的技术。 图像识别技术可能是以图像的主要特征为基础的。每个图像都有它的特征，如字母A有个尖，P有个圈、而Y的中心有个锐角等。由此可见，在图像识别过程中，知觉机制必须排除输入的多余信息,抽出关键的信息。同时,在大脑里必定有一个负责整合信息的机制，它能把分阶段获得的信息整理成一个完整的知觉映象。\",\"questionId\":129,\"questionScore\":100,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":192}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":0}}', 0, NULL, '2026-03-09 09:07:02', 20);
