INSERT INTO `sys_oper_log` VALUES (650, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '675077', '塔山中学', '/business/lesson/save-all', '127.0.0.1', '内网IP', '{\"assignedClassCodes\":[\"809班\",\"810班\",\"811班\"],\"grade\":8,\"lessonId\":37,\"lessonNum\":1,\"lessonTitle\":\"图像识别技术\",\"params\":{},\"questions\":[{\"lessonId\":37,\"orderNum\":1,\"params\":{},\"questionContent\":\"图像识别技术是人工智能的一个重要领域。它是指对图像进行对象识别，以识别各种不同模式的目标和对像的技术。 图像识别技术可能是以图像的主要特征为基础的。每个图像都有它的特征，如字母A有个尖，P有个圈、而Y的中心有个锐角等。由此可见，在图像识别过程中，知觉机制必须排除输入的多余信息,抽出关键的信息。同时,在大脑里必定有一个负责整合信息的机制，它能把分阶段获得的信息整理成一个完整的知觉映象。\",\"questionId\":129,\"questionScore\":40,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":192},{\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/09/导学单 - 图像识别技术_20260309093017A180.pdf\",\"questionContent\":\"上传图像识别导学单\",\"questionId\":130,\"questionScore\":60,\"questionType\":\"practical\",\"scoringItems\":[{\"createTime\":\"2026-03-09 09:30:38\",\"itemId\":25,\"itemName\":\"分析正确\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":130,\"updateTime\":\"2026-03-09 09:30:38\"}]}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":0}', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"809班\",\"810班\",\"811班\"],\"grade\":8,\"lessonId\":37,\"lessonNum\":1,\"lessonTitle\":\"图像识别技术\",\"params\":{},\"questions\":[{\"lessonId\":37,\"orderNum\":1,\"params\":{},\"questionContent\":\"图像识别技术是人工智能的一个重要领域。它是指对图像进行对象识别，以识别各种不同模式的目标和对像的技术。 图像识别技术可能是以图像的主要特征为基础的。每个图像都有它的特征，如字母A有个尖，P有个圈、而Y的中心有个锐角等。由此可见，在图像识别过程中，知觉机制必须排除输入的多余信息,抽出关键的信息。同时,在大脑里必定有一个负责整合信息的机制，它能把分阶段获得的信息整理成一个完整的知觉映象。\",\"questionId\":129,\"questionScore\":40,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":192},{\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/09/导学单 - 图像识别技术_20260309093017A180.pdf\",\"questionContent\":\"上传图像识别导学单\",\"questionId\"