INSERT INTO `sys_oper_log` VALUES (663, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '675077', '塔山中学', '/business/question', '127.0.0.1', '内网IP', '{\"createBy\":\"675077\",\"createTime\":\"2026-03-09 11:26:22\",\"creatorId\":896,\"filePath\":\"/profile/upload/2026/03/09/灯塔操作手册_20260309112613A182.docx\",\"grade\":7,\"isPublic\":\"Y\",\"lessonNum\":1,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/09/灯塔操作手册_20260309112613A182.pdf\",\"previewStatus\":\"pending\",\"questionContent\":\"上传生成二维码\",\"questionId\":132,\"questionType\":\"practical\",\"scoringItems\":[{\"itemId\":27,\"itemName\":\"上传正确\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":132}],\"semester\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-09 11:26:22', 15);
INSERT INTO `sys_oper_log` VALUES (664, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '675077', '塔山中学', '/business/lesson/save-all', '127.0.0.1', '内网IP', '{\"assignedClassCodes\":[\"1班\",\"3班\",\"4班\",\"5班\",\"6班\",\"7班\",\"8班\",\"9班\",\"10班\",\"2班\"],\"grade\":7,\"lessonId\":36,\"lessonNum\":1,\"lessonTitle\":\"感知与识别\",\"params\":{},\"questions\":[{\"lessonId\":36,\"orderNum\":1,\"params\":{},\"questionContent\":\"物联网就像给世界装上了 “五官”，能让物体互相交流、自动工作，而感知与识别技术就是它的核心。感知技术依靠传感器，能收集温度、湿度、光线、声音等信息，就像我们用眼睛看、耳朵听。识别技术可以分辨物体、人脸、指纹和二维码，让设备 “认出” 目标。在生活里，这些技术随处可见：智能手环感知心跳，超市扫码器识别商品，门禁刷脸开门，智能家居根据环境自动调节。它们让生活更方便、更安全。\",\"questionId\":128,\"questionScore\":60,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":183},{\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/09/灯塔操作手册_20260309112613A182.pdf\",\"questionContent\":\"上传生成二维码\",\"questionId\":132,\"questionScore\":40,\"questionType\":\"practical\",\"scoringItems\":[{\"createTime\":\"2026-03-09 11:26:22\",\"itemId\":27,\"itemName\":\"上传正确\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":132,\"updateTime\":\"2026-03-09 11:26:22\"}]}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":0}', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"1班\",\"3班\",\"4班\",\"5班\",\"6班\",\"7班\",\"8班\",\"9班\",\"10班\",\"2班\"],\"grade\":7,\"lessonId\":36,\"lessonNum\":1,\"lessonTitle\":\"感知与识别\",\"params\":{},\"questions\":[{\"lessonId\":36,\"orderNum\":1,\"params\":{},\"questionContent\":\"物联网就像给世界装上了 “五官”，能让物体互相交流、自动工作，而感知与识别技术就是它的核心。感知技术依靠传感器，能收集温度、湿度、光线、声音等信息，就像我们用眼睛看、耳朵听。识别技术可以分辨物体、人脸、指纹和二维码，让设备 “认出” 目标。在生活里，这些技术随处可见：智能手环感知心跳，超市扫码器识别商品，门禁刷脸开门，智能家居根据环境自动调节。它们让生活更方便、更安全。\",\"questionId\":128,\"questionScore\":60,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":183},{\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/09/灯塔操作手册_20260309112613A182.pdf\",\"questionContent\":\"上传生成二维码\",\"questionId\":132,\"questionScore\":40,\"questionType\":\"practical\",\"scoringItems\":[{\"createTime\":\"2026-03-09 11:26:22\",\"itemId\":27,\"itemName\":\"上传正确\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":132,\"updateTime\":\"2026-03-09 11:26:22\"}]}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":0}}', 0, NULL, '2026-03-09 11:26:42', 31);
