INSERT INTO `sys_oper_log` VALUES (770, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, 'dmw15', '丹城五小', '/business/lesson/save-all', '127.0.0.1', '内网IP', '{\"assignedClassCodes\":[\"1班\"],\"grade\":6,\"lessonId\":41,\"lessonNum\":1,\"lessonTitle\":\"实施\",\"params\":{},\"questions\":[{\"orderNum\":1,\"params\":{},\"questionContent\":\"在自动控制系统中，将输出量通过检测装置反馈到输入端并与输入量进行比较的过程，就是反馈 。通过输出量和输入量的比较，实现控制系统的输出在预设范围内，反馈在其中发挥了重要的作用 。反馈在保证系统正常运行中也发挥了重要的作用 。\",\"questionId\":124,\"questionScore\":100,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":6,\"wordCount\":108}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":0}', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"1班\"],\"grade\":6,\"lessonId\":41,\"lessonNum\":1,\"lessonTitle\":\"实施\",\"params\":{},\"questions\":[{\"orderNum\":1,\"params\":{},\"questionContent\":\"在自动控制系统中，将输出量通过检测装置反馈到输入端并与输入量进行比较的过程，就是反馈 。通过输出量和输入量的比较，实现控制系统的输出在预设范围内，反馈在其中发挥了重要的作用 。反馈在保证系统正常运行中也发挥了重要的作用 。\",\"questionId\":124,\"questionScore\":100,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":6,\"wordCount\":108}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":0}}', 0, NULL, '2026-03-11 10:36:01', 19);
