INSERT INTO `sys_oper_log` VALUES (792, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '960250', '大目湾学校(初中部)', '/business/lesson/save-all', '127.0.0.1', '内网IP', '{\"assignedClassCodes\":[\"3班\",\"4班\",\"5班\",\"6班\",\"7班\",\"8班\",\"9班\",\"10班\",\"2班\"],\"grade\":7,\"lessonId\":36,\"lessonNum\":2,\"lessonTitle\":\"走进物联网\",\"params\":{},\"questions\":[{\"answer\":\"\",\"lessonId\":36,\"optionA\":\"\",\"optionB\":\"\",\"optionC\":\"\",\"optionD\":\"\",\"orderNum\":1,\"params\":{},\"questionContent\":\"物联网是互联网充分发展的产物，是物理世界和数字世界之间的桥梁。物联网具有全面感知、可靠传递、智能处理等特征。物联网一般由感知层、网络层、平台层、应用层四层组成。感知层是物联网的底层，相当于人的眼、耳等器官，负责物联网的物体识别和信息采集。感知层是物联网的底层，相当于人的眼、耳等器官，负责物联网的物体识别和信息采集。平台层是在云平台基础上构建的基础计算设施，功能相当于人的大脑，运用智能技术对海量数据和信息进行处理。应用层是物联网和用户的接口。\",\"questionId\":167,\"questionScore\":60,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":6,\"wordCount\":222},{\"answer\":\"D\",\"lessonId\":36,\"optionA\":\"应用层\",\"optionB\":\"平台层\",\"optionC\":\"网络层\",\"optionD\":\"感知层\",\"orderNum\":2,\"params\":{},\"questionContent\":\"水分传感器是物联网架构中（     ）的设备？\",\"questionId\":161,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"D\",\"lessonId\":36,\"optionA\":\"全面感知\",\"optionB\":\"可靠传递\",\"optionC\":\"可靠决策\",\"optionD\":\"智能处理\",\"orderNum\":3,\"params\":{},\"questionContent\":\"利用云计算、数据挖掘以及模糊识别等智能技术，对接收到的海量数据与信息进行分析、处理，以进行智能化决策，体现了物联网的（         ）特征。\",\"questionId\":162,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"lessonId\":36,\"optionA\":\"应用层\",\"optionB\":\"平台层\",\"optionC\":\"网络层\",\"optionD\":\"感知层\",\"orderNum\":4,\"params\":{},\"questionContent\":\"物联网的（       ）功能相当于人的大脑，运用智能技术对海量数据和信息进行处理。\",\"questionId\":163,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"lessonId\":36,\"optionA\":\"应用层\",\"optionB\":\"平台层\",\"optionC\":\"网络层\",\"optionD\":\"感知层\",\"orderNum\":5,\"params\":{},\"questionContent\":\"自动浇灌物联系统原型中，物联数据中台是属于（    